insert into public.challenges (id,title,kind,question,options,market,chart_t,side,points,max_winners,starts_at,ends_at,status) values ('45ecace6-ef87-5cf9-9999-c9ed5b3fe3b4','¿Qué te muestra una vela japonesa?','opcion','Pregunta básica: cada vela del gráfico resume lo que hizo el precio en un periodo. ¿Qué información trae?','["Solo el precio de cierre", "La apertura, el máximo, el mínimo y el cierre de ese periodo", "El volumen de operaciones del día", "Hacia dónde va el precio en la siguiente vela"]'::jsonb,'',null,'buy',100,5,'2026-11-11T13:00:00+00:00','2026-11-12T13:00:00+00:00','publicado') on conflict (id) do nothing;
insert into public.challenge_keys (challenge_id,correct,zone,tol,explain) values ('45ecace6-ef87-5cf9-9999-c9ed5b3fe3b4',1,null,null,'Cada vela muestra cuatro precios del periodo: apertura, máximo, mínimo y cierre. El cuerpo va de la apertura al cierre y las mechas marcan el máximo y el mínimo.') on conflict (challenge_id) do nothing;
insert into public.challenges (id,title,kind,question,options,market,chart_t,side,points,max_winners,starts_at,ends_at,status) values ('25a4dd72-26a4-5dbc-a7cc-f3e4ca7d7cea','Boom 1000: ¿sube o baja?','tendencia','Boom 1000 en H1. El precio viene cayendo y frenó abajo. ¿Dónde estará dentro de 24 velas de H1 (un día): más arriba o más abajo que ahora?','["Sube", "Baja"]'::jsonb,'B1000',1784073600,'buy',100,5,'2026-11-12T13:00:00+00:00','2026-11-13T13:00:00+00:00','publicado') on conflict (id) do nothing;
insert into public.challenge_keys (challenge_id,correct,zone,tol,explain) values ('25a4dd72-26a4-5dbc-a7cc-f3e4ca7d7cea',0,null,null,'Subió. En las 24 velas siguientes pasó de 14240 a 14692 (unos 450 puntos): el precio dejó de hacer mínimos nuevos y los spikes lo llevaron arriba.') on conflict (challenge_id) do nothing;
insert into public.challenges (id,title,kind,question,options,market,chart_t,side,points,max_winners,starts_at,ends_at,status) values ('75721b1d-7ab5-5291-a702-f44746c60a99','¿Para qué sirve el stop loss?','opcion','Pregunta básica de gestión del riesgo.','["Para asegurar que la operación termine en ganancia", "Para limitar cuánto pierdes si el precio va en tu contra", "Para abrir una operación más grande", "Para cerrar la plataforma automáticamente"]'::jsonb,'',null,'buy',100,5,'2026-11-13T13:00:00+00:00','2026-11-14T13:00:00+00:00','publicado') on conflict (id) do nothing;
insert into public.challenge_keys (challenge_id,correct,zone,tol,explain) values ('75721b1d-7ab5-5291-a702-f44746c60a99',1,null,null,'El stop loss cierra la operación en un precio que tú decides antes de entrar, para que una operación que sale mal no te cueste más de lo que planeaste arriesgar.') on conflict (challenge_id) do nothing;
insert into public.challenges (id,title,kind,question,options,market,chart_t,side,points,max_winners,starts_at,ends_at,status) values ('760ede27-c6b1-5336-8d5e-ca462e62bc10','Boom 300: ¿por dónde rompe el rango?','tendencia','Boom 300 en H1. El precio lleva un día moviéndose entre 487 y 523. ¿Qué rompe primero en las próximas velas: el techo o el piso?','["Rompe hacia arriba (el techo, 523)", "Rompe hacia abajo (el piso, 487)"]'::jsonb,'B300',1788714000,'buy',100,5,'2026-11-14T13:00:00+00:00','2026-11-15T13:00:00+00:00','publicado') on conflict (id) do nothing;
insert into public.challenge_keys (challenge_id,correct,zone,tol,explain) values ('760ede27-c6b1-5336-8d5e-ca462e62bc10',1,null,null,'Rompió hacia abajo. Aunque estaba cerca del techo, no lo superó: 10 velas después cerró por debajo de 487 y siguió cayendo hasta por debajo de 430.') on conflict (challenge_id) do nothing;
insert into public.challenges (id,title,kind,question,options,market,chart_t,side,points,max_winners,starts_at,ends_at,status) values ('fb4c9b7c-73e2-51ed-80be-d21cecb39672','Tendencia alcista: ¿qué forma el precio?','opcion','Pregunta básica de estructura del mercado.','["Máximos y mínimos cada vez más altos", "Máximos y mínimos cada vez más bajos", "Máximos y mínimos siempre al mismo nivel", "Solo velas verdes, sin ninguna roja"]'::jsonb,'',null,'buy',100,5,'2026-11-15T13:00:00+00:00','2026-11-16T13:00:00+00:00','publicado') on conflict (id) do nothing;
insert into public.challenge_keys (challenge_id,correct,zone,tol,explain) values ('fb4c9b7c-73e2-51ed-80be-d21cecb39672',0,null,null,'En una tendencia alcista cada máximo supera al anterior y cada retroceso se queda por encima del mínimo anterior. Puede haber velas rojas: lo que importa es la estructura.') on conflict (challenge_id) do nothing;
insert into public.challenges (id,title,kind,question,options,market,chart_t,side,points,max_winners,starts_at,ends_at,status) values ('b33e2e4d-3a8a-5aac-ab27-d4b81f4018fc','Crash 500: ¿sube o baja?','tendencia','Crash 500 en H1. Viene de una subida fuerte. ¿Dónde estará dentro de 24 velas de H1 (un día): más arriba o más abajo que ahora?','["Sube", "Baja"]'::jsonb,'C500',1792537200,'buy',100,5,'2026-11-16T13:00:00+00:00','2026-11-17T13:00:00+00:00','publicado') on conflict (id) do nothing;
insert into public.challenge_keys (challenge_id,correct,zone,tol,explain) values ('b33e2e4d-3a8a-5aac-ab27-d4b81f4018fc',1,null,null,'Bajó. Justo después llegaron las caídas: en 24 velas pasó de 3118 a 2999. Una subida larga en Crash no garantiza que siga; el precio estaba lejos de cualquier zona de apoyo.') on conflict (challenge_id) do nothing;
insert into public.challenges (id,title,kind,question,options,market,chart_t,side,points,max_winners,starts_at,ends_at,status) values ('a5bc0ce0-a712-50c5-914a-4231e6354978','Calcula tu resultado en R','opcion','Pregunta básica: arriesgas 10 USD (la distancia a tu stop loss) y la operación te deja 20 USD de ganancia. ¿Cuál es tu resultado en R?','["+0,5 R", "+1 R", "+2 R", "+20 R"]'::jsonb,'',null,'buy',100,5,'2026-11-17T13:00:00+00:00','2026-11-18T13:00:00+00:00','publicado') on conflict (id) do nothing;
insert into public.challenge_keys (challenge_id,correct,zone,tol,explain) values ('a5bc0ce0-a712-50c5-914a-4231e6354978',2,null,null,'1 R es lo que arriesgas, en este caso 10 USD. Si ganas 20 USD, ganaste el doble de lo arriesgado: +2 R.') on conflict (challenge_id) do nothing;
insert into public.challenges (id,title,kind,question,options,market,chart_t,side,points,max_winners,starts_at,ends_at,status) values ('e834b8e4-b5db-5e68-ad0e-c83a564cf46d','Crash 1000: ¿por dónde rompe el rango?','tendencia','Crash 1000 en H1. El último día el precio se movió entre 5892 y 5985. ¿Qué rompe primero en las próximas velas: el techo o el piso?','["Rompe hacia arriba (el techo, 5985)", "Rompe hacia abajo (el piso, 5892)"]'::jsonb,'C1000',1788105600,'buy',100,5,'2026-11-18T13:00:00+00:00','2026-11-19T13:00:00+00:00','publicado') on conflict (id) do nothing;
insert into public.challenge_keys (challenge_id,correct,zone,tol,explain) values ('e834b8e4-b5db-5e68-ad0e-c83a564cf46d',0,null,null,'Rompió hacia arriba. Venía haciendo mínimos más altos desde el piso; 6 velas después cerró por encima de 5985 y llegó hasta la zona de 6070.') on conflict (challenge_id) do nothing;
insert into public.challenges (id,title,kind,question,options,market,chart_t,side,points,max_winners,starts_at,ends_at,status) values ('0ffb0412-d4ad-5acf-aab7-6065b3a941b6','¿Qué es Boom 1000?','opcion','Pregunta básica sobre los índices sintéticos.','["Un índice con caídas bruscas cada cierto número de ticks", "Un índice con subidas bruscas (spikes) en promedio cada 1000 ticks", "Una acción de una empresa tecnológica", "Un índice que se mueve con las noticias económicas"]'::jsonb,'',null,'buy',100,5,'2026-11-19T13:00:00+00:00','2026-11-20T13:00:00+00:00','publicado') on conflict (id) do nothing;
insert into public.challenge_keys (challenge_id,correct,zone,tol,explain) values ('0ffb0412-d4ad-5acf-aab7-6065b3a941b6',1,null,null,'Boom 1000 es un índice sintético de Deriv: entre spikes el precio tiende a bajar poco a poco y, en promedio cada 1000 ticks, da una subida brusca. Crash es lo contrario: caídas bruscas.') on conflict (challenge_id) do nothing;
